-- Лишние пробелы в ФИО у уже сохранённых записей (новые сохранения приложение чистит само, с 14.10.2026).
-- Края обрезаются, двойные пробелы и неразрывный пробел -> один пробел. Повторный запуск безопасен.
update crm_clients set surname = trim(replace(replace(replace(replace(surname, _utf8 x'C2A0', ' '), '    ', ' '), '  ', ' '), '  ', ' ')) where surname is not null and (surname like '% ' or surname like ' %' or surname like '%  %' or surname like concat('%', _utf8 x'C2A0', '%'));
update crm_clients set name = trim(replace(replace(replace(replace(name, _utf8 x'C2A0', ' '), '    ', ' '), '  ', ' '), '  ', ' ')) where name is not null and (name like '% ' or name like ' %' or name like '%  %' or name like concat('%', _utf8 x'C2A0', '%'));
update crm_clients set middlename = trim(replace(replace(replace(replace(middlename, _utf8 x'C2A0', ' '), '    ', ' '), '  ', ' '), '  ', ' ')) where middlename is not null and (middlename like '% ' or middlename like ' %' or middlename like '%  %' or middlename like concat('%', _utf8 x'C2A0', '%'));
update patients set surname = trim(replace(replace(replace(replace(surname, _utf8 x'C2A0', ' '), '    ', ' '), '  ', ' '), '  ', ' ')) where surname is not null and (surname like '% ' or surname like ' %' or surname like '%  %' or surname like concat('%', _utf8 x'C2A0', '%'));
