update patients set middlename = trim(replace(replace(replace(replace(middlename, _utf8 x'C2A0', ' '), '    ', ' '), '  ', ' '), '  ', ' ')) where middlename is not null and (middlename like '% ' or middlename like ' %' or middlename like '%  %' or middlename like concat('%', _utf8 x'C2A0', '%'));
update amb_patients set surname = trim(replace(replace(replace(replace(surname, _utf8 x'C2A0', ' '), '    ', ' '), '  ', ' '), '  ', ' ')) where surname is not null and (surname like '% ' or surname like ' %' or surname like '%  %' or surname like concat('%', _utf8 x'C2A0', '%'));
update amb_patients set name = trim(replace(replace(replace(replace(name, _utf8 x'C2A0', ' '), '    ', ' '), '  ', ' '), '  ', ' ')) where name is not null and (name like '% ' or name like ' %' or name like '%  %' or name like concat('%', _utf8 x'C2A0', '%'));
update amb_patients set middlename = trim(replace(replace(replace(replace(middlename, _utf8 x'C2A0', ' '), '    ', ' '), '  ', ' '), '  ', ' ')) where middlename is not null and (middlename like '% ' or middlename like ' %' or middlename like '%  %' or middlename like concat('%', _utf8 x'C2A0', '%'));
update amb_bookings set surname = trim(replace(replace(replace(replace(surname, _utf8 x'C2A0', ' '), '    ', ' '), '  ', ' '), '  ', ' ')) where surname is not null and (surname like '% ' or surname like ' %' or surname like '%  %' or surname like concat('%', _utf8 x'C2A0', '%'));
update amb_bookings set name = trim(replace(replace(replace(replace(name, _utf8 x'C2A0', ' '), '    ', ' '), '  ', ' '), '  ', ' ')) where name is not null and (name like '% ' or name like ' %' or name like '%  %' or name like concat('%', _utf8 x'C2A0', '%'));
